"""Package the actual fresh-run film as a responsive, inspectable launch player."""
from pathlib import Path
import base64, html, json, re, shutil
project = Path(__file__).resolve().parent
repo = project.parents[1]
preview = repo / '.lavish'
assets = preview / 'contexttrail-assets'
assets.mkdir(exist_ok=True, parents=True)
timing = json.loads((project/'fresh-timing.json').read_text())
request = json.loads((project/'audio_request_fresh.json').read_text())
for name in ['instrument-serif-latin.woff2','instrument-serif-latin-italic.woff2','geist-sans-latin.woff2']:
    shutil.copy2(project/'assets/fonts'/name, assets/name)
shutil.copy2(project/'renders/contexttrail-launch-fresh.mp4', assets/'contexttrail-launch-fresh.mp4')
shutil.copy2(project/'renders/contexttrail-launch-fresh-poster.jpg', assets/'poster-fresh.jpg')
